#include <stdio.h>
#include <stdlib.h>

int knapsack(int *weights, int *values, int capacity, int n) {
    //code here..
         int dp[n + 1][capacity + 1];

    // Initialize DP table
    for (int i = 0; i <= n; i++) {
        for (int w = 0; w <= capacity; w++) {

            if (i == 0 || w == 0) {
                dp[i][w] = 0;
            }
            else if (weights[i - 1] <= w) {

                int include = values[i - 1] +
                              dp[i - 1][w - weights[i - 1]];

                int exclude = dp[i - 1][w];

                if (include > exclude)
                    dp[i][w] = include;
                else
                    dp[i][w] = exclude;
            }
            else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }

    return dp[n][capacity];
}


int main() {
    int n;

    // Read number of items
    scanf("%d", &n);

    // Allocate memory for values and weights
    int *values = (int *)malloc(n * sizeof(int));
    int *weights = (int *)malloc(n * sizeof(int));

    // Read values and weights of items
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &values[i],&weights[i]);
    }

    int capacity;
    scanf("%d", &capacity);

    // Calculate and print the maximum profit
    printf("%d\n", knapsack(weights, values, capacity, n));

    // Free allocated memory
    free(values);
    free(weights);

    return 0;
}

package q105748;
import java.util.Scanner;

class Shape {
    void calculateArea() {
        System.out.println("0.00");
    }
}

class Polygon extends Shape {
    int sides;
    double sideLength;

    Polygon(int sides, double sideLength) {
        this.sides=sides;
        this.sideLength=sideLength;
    }

    @Override
    void calculateArea() {
        double perimeter =sides*sideLength;
        System.out.printf("%.2f\n",perimeter);
    }
}

class Triangle extends Polygon {
    double height;

    Triangle(int sides, double sideLength, double height) {
        super(sides,sideLength);
        this.height=height;
    }

    @Override
    void calculateArea() {
        double area =0.5*sideLength*height;
        System.out.printf("%.2f\n",area);
    }
}

public class ShapeHierarchy {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int sides = sc.nextInt();
        double sideLength = sc.nextDouble();
        double height = sc.nextDouble();
        Shape shape = new Shape();
        Shape polygon = new Polygon(sides, sideLength);
        Shape triangle = new Triangle(sides, sideLength, height);
        shape.calculateArea();
        polygon.calculateArea();
        triangle.calculateArea();
    }
}

